    31	/**
    32	 * 封装 wx.request，返回 Promise
    33	 * @param {'GET'|'POST'|'PUT'|'DELETE'} method
    34	 * @param {string} path — 如 '/items?scope=personal'
    35	 * @param {*} data — 请求体（仅 POST/PUT）
    36	 */
    37	function _request(method, path, data) {
    38	  const token = _getToken()
    39	  return new Promise((resolve, reject) => {
    40	    wx.request({
    41	      url: BASE_URL + path,
    42	      method,
    43	      header: {
    44	        'Content-Type': 'application/json',
    45	        ...(token ? { 'Authorization': 'Bearer ' + token } : {})
    46	      },
    47	      data: data || undefined,
    48	      success(res) {
    49	        if (res.statusCode >= 200 && res.statusCode < 300) {
    50	          resolve(res.data)
    51	        } else {
    52	          console.warn('[API]', method, path, res.statusCode, res.data)
    53	          reject(res.data)
    54	        }
    55	      },
    56	      fail(err) {
    57	        console.error('[API]', method, path, '网络错误', err)
    58	        reject(err)
    59	      }
    60	    })
    61	  })
    62	}
