    64	/**
    65	 * 后台推送 — 异步写入后端，不阻塞调用方
    66	 * 无 token 时直接跳过（离线模式）
    67	 */
    68	function _pushBackend(method, path, data) {
    69	  if (!_getToken()) return // 未登录，仅用本地存储
    70	  return _request(method, path, data).catch(err => {
    71	    console.warn('[API] 后台推送失败', path, err)
